begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('80000000-0000-4000-8000-000000000001');
insert into auth.sessions(id,user_id) values('81000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000001');
insert into public.portal_profiles(id,role,active) values('80000000-0000-4000-8000-000000000001','recepcao',true);
create temporary table stay_command(command jsonb);
insert into stay_command values('{"id":"82000000-0000-4000-8000-000000000001","apartment":"TEST-A","arrival_date":"2026-10-09","departure_date":"2026-10-12"}');
grant select on stay_command to authenticated;
select ok((select relrowsecurity from pg_class where oid='public.portal_stays'::regclass),'Registry RLS enabled');
select ok(not has_table_privilege('anon','public.portal_stays','select'),'Anonymous cannot read registry');
select ok(not has_table_privilege('authenticated','public.portal_stays','insert,update,delete'),'Client has no direct writes');
select ok(not has_function_privilege('anon','public.portal_create_stay(uuid,jsonb)','execute'),'Anonymous cannot execute RPC');
select ok(not has_function_privilege('service_role','public.portal_create_stay(uuid,jsonb)','execute'),'No administrative operational writer');
select throws_ok($$select public.portal_create_stay(gen_random_uuid(),(select command from stay_command))$$,'P0001','E_FORBIDDEN','Missing Auth denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000001","session_id":"81000000-0000-4000-8000-000000000001"}',true);
select ok(private.has_permission('stays.read') and private.has_permission('stays.manage'),'Reception has central stay permissions');
select is(public.portal_create_stay('83000000-0000-4000-8000-000000000001',(select command from stay_command)),'82000000-0000-4000-8000-000000000001'::uuid,'Reception creates own stay');
select is(public.portal_create_stay('83000000-0000-4000-8000-000000000001',(select command from stay_command)),'82000000-0000-4000-8000-000000000001'::uuid,'Retry returns same stay');
select is((select count(*) from public.portal_stays),1::bigint,'Retry does not duplicate stay');
select throws_ok($$select public.portal_create_stay('83000000-0000-4000-8000-000000000001',(select command||'{"apartment":"TEST-B"}'::jsonb from stay_command))$$,'P0001','E_IDEMPOTENCY','Retry with changed data rejected');
select throws_ok($$select public.portal_create_stay(gen_random_uuid(),(select command from stay_command))$$,'P0001','E_VERSION','Repeated entity with new request rejected');
select throws_ok($$select public.portal_create_stay(gen_random_uuid(),(select command||'{"id":"82000000-0000-4000-8000-000000000002","departure_date":"2026-10-08"}'::jsonb from stay_command))$$,'P0001','E_INPUT','Inverted period rejected');
select throws_ok($$select public.portal_create_stay(gen_random_uuid(),(select command||'{"arrival_date":"2026-02-30"}'::jsonb from stay_command))$$,'P0001','E_INPUT','Impossible civil date rejected');
select throws_ok($$select public.portal_create_stay(gen_random_uuid(),(select command||'{"role":"admin"}'::jsonb from stay_command))$$,'P0001','E_INPUT','Unexpected data rejected');
select throws_ok($$select public.portal_create_stay(gen_random_uuid(),(select command||'{"apartment":null}'::jsonb from stay_command))$$,'P0001','E_INPUT','Null field rejected');
select throws_ok($$select public.portal_create_stay(gen_random_uuid(),(select command||'{"arrival_date":"2026-1-09"}'::jsonb from stay_command))$$,'P0001','E_INPUT','Noncanonical date rejected');
select lives_ok($$select public.portal_create_stay(gen_random_uuid(),(select command||'{"id":"82000000-0000-4000-8000-000000000002","departure_date":"2026-10-09"}'::jsonb from stay_command))$$,'Same-day stay accepted');
reset role;
select is((select count(*) from public.audit_events where entity_type='portal_stays'),2::bigint,'Successful creations audited exactly once');
select ok((select bool_and(not after ?| array['apartment','guest_name','notes']) from public.audit_events where entity_type='portal_stays'),'Audit excludes free text');
create function private.stay_test_fail_audit() returns trigger language plpgsql as $$begin raise exception 'Synthetic audit failure'; end;$$;
create trigger stay_test_fail_audit before insert on public.audit_events for each row execute function private.stay_test_fail_audit();
set local role authenticated;
select throws_ok($$select public.portal_create_stay('83000000-0000-4000-8000-000000000003',(select command||'{"id":"82000000-0000-4000-8000-000000000003"}'::jsonb from stay_command))$$,'P0001','Synthetic audit failure','Audit failure aborts registry creation');
select is((select count(*) from public.portal_stays where id='82000000-0000-4000-8000-000000000003'),0::bigint,'Failed audit leaves no stay');
reset role;
select is((select count(*) from private.mutation_requests where request_id='83000000-0000-4000-8000-000000000003'),0::bigint,'Failed audit leaves no receipt');
drop trigger stay_test_fail_audit on public.audit_events;
select set_config('request.jwt.claims','{}',true);
insert into auth.users(id) values('80000000-0000-4000-8000-000000000002');
insert into auth.sessions(id,user_id) values('81000000-0000-4000-8000-000000000002','80000000-0000-4000-8000-000000000002');
insert into public.portal_profiles(id,role,active) values('80000000-0000-4000-8000-000000000002','gerencia',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000002","session_id":"81000000-0000-4000-8000-000000000002"}',true);
select is(public.portal_create_stay('83000000-0000-4000-8000-000000000001',(select command||'{"id":"82000000-0000-4000-8000-000000000003"}'::jsonb from stay_command)),'82000000-0000-4000-8000-000000000003'::uuid,'Request identity is isolated per operator');
reset role;
select set_config('request.jwt.claims','{}',true);
update public.portal_profiles set active=false where id='80000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000001","session_id":"81000000-0000-4000-8000-000000000001"}',true);
select is((select count(*) from public.portal_stays),0::bigint,'Inactive profile cannot read stays');
select throws_ok($$select public.portal_create_stay(gen_random_uuid(),(select command from stay_command))$$,'P0001','E_FORBIDDEN','Inactive profile cannot write');
reset role;
select set_config('request.jwt.claims','{}',true);
update public.portal_profiles set active=true where id='80000000-0000-4000-8000-000000000001';
delete from auth.sessions where user_id='80000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000001","session_id":"81000000-0000-4000-8000-000000000001"}',true);
select is((select count(*) from public.portal_stays),0::bigint,'Revoked session cannot read stays');
select throws_ok($$select public.portal_create_stay(gen_random_uuid(),(select command from stay_command))$$,'P0001','E_FORBIDDEN','Revoked session cannot write');
reset role;
select * from finish();
rollback;
